<!DOCTYPE html>
<html>
<head>
    <title>アニメファン</title>
    <meta charset="UTF-8">
    <meta http-equiv="X-UA-Compatible" content="IE=edge">
    <meta name='robots' content='noindex, nofollow, noarchive'>
    <link href="https://fonts.googleapis.com/css2?family=Space+Grotesk:wght@300..700&display=swap" rel="stylesheet">
    
    <style>
    body {
        font-family: "Space Grotesk", sans-serif;
        color: #fff;
        margin: 0;
        padding: 0;
        background-color: #000;
    }

    .result-box-container {
    position: relative;
    margin-top: 20px;
}

.result-box {
    width: 100%;
    height: 200px;
    padding: 10px;
    border: 1px solid #ddd;
    border-radius: 5px;
    background-color: #333;
    overflow: auto;
    box-sizing: border-box;
    font-family: "Space Grotesk", sans-serif;
    color: #fff;
    resize: both;
    min-height: 100px;
    max-height: 500px;
}

.result-box::placeholder {
    color: #999;
}

.result-box:focus {
    outline: none;
    border-color: #fff;
}

.result-box::-webkit-scrollbar {
    width: 8px;
}

.result-box::-webkit-scrollbar-thumb {
    background-color: #53585d;
    border-radius: 4px;
}


    .container {
        max-width: 90%;
        margin: 20px auto;
        padding: 20px;
        background-color: #1a1a1a;
        border-radius: 44px;
        box-shadow: 0 0 10px rgba(255, 255, 255, 0.1);
    }

    .header {
        text-align: center;
        margin-bottom: 20px;
    }

    .header h1 {
        font-size: 24px;
        color: #fff;
    }

    .subheader {
        text-align: center;
        margin-bottom: 20px;
    }

    .subheader p {
        font-size: 16px;
        font-style: italic;
        color: #ccc;
    }

    form {
        margin-bottom: 20px;
    }

    form input[type="text"],
    form textarea {
        font-family: "Space Grotesk", sans-serif;
        padding: 8px;
        margin-bottom: 10px;
        border: 1px solid #fff;
        border-radius: 3px;
        box-sizing: border-box;
        background-color: #333;
        color: #fff;
    }

    form input[type="submit"] {
        padding: 10px;
        color: #000;
        font-weight: bold;
        font-family: "Space Grotesk", sans-serif;
        border: none;
        border-radius: 3px;
        cursor: pointer;
        animation: rgbBtnBg 3s linear infinite;
    }

    form input[type="file"] {
        padding: 7px;
        color: #000;
        font-weight: bold;
        font-family: "Space Grotesk", sans-serif;
        border: none;
        border-radius: 3px;
        cursor: pointer;
        animation: rgbBtnBg 3s linear infinite;
    }

    form input[type="submit"]:hover, form input[type="file"]:hover {
        animation: rgbBtnBgHover 1s linear infinite;
        transform: scale(1.05);
    }

    @keyframes rgbBtnBg {
        0%   { background-color: #ff3b3b; box-shadow: 0 0 8px #ff3b3b; }
        16%  { background-color: #ffa500; box-shadow: 0 0 8px #ffa500; }
        33%  { background-color: #ffff00; box-shadow: 0 0 8px #ffff00; }
        50%  { background-color: #33ff33; box-shadow: 0 0 8px #33ff33; }
        66%  { background-color: #3b8bff; box-shadow: 0 0 8px #3b8bff; }
        83%  { background-color: #b43bff; box-shadow: 0 0 8px #b43bff; }
        100% { background-color: #ff3b3b; box-shadow: 0 0 8px #ff3b3b; }
    }
    @keyframes rgbBtnBgHover {
        0%   { background-color: #ffffff; box-shadow: 0 0 14px #ff3b3b; }
        25%  { background-color: #e6ffe6; box-shadow: 0 0 14px #33ff33; }
        50%  { background-color: #e6e6ff; box-shadow: 0 0 14px #3b8bff; }
        75%  { background-color: #ffe6ff; box-shadow: 0 0 14px #b43bff; }
        100% { background-color: #ffffff; box-shadow: 0 0 14px #ff3b3b; }
    }

    form input[type="text"], form textarea, textarea[name="file_content"] {
        animation: rgbInputBorder 4s linear infinite;
    }
    @keyframes rgbInputBorder {
        0%   { border-color: rgba(255,0,0,0.9); box-shadow: 0 0 6px rgba(255,0,0,0.4); }
        16%  { border-color: rgba(255,165,0,0.9); box-shadow: 0 0 6px rgba(255,165,0,0.4); }
        33%  { border-color: rgba(255,255,0,0.9); box-shadow: 0 0 6px rgba(255,255,0,0.4); }
        50%  { border-color: rgba(0,255,0,0.9); box-shadow: 0 0 6px rgba(0,255,0,0.4); }
        66%  { border-color: rgba(0,100,255,0.9); box-shadow: 0 0 6px rgba(0,100,255,0.4); }
        83%  { border-color: rgba(150,0,255,0.9); box-shadow: 0 0 6px rgba(150,0,255,0.4); }
        100% { border-color: rgba(255,0,0,0.9); box-shadow: 0 0 6px rgba(255,0,0,0.4); }
    }

    .result-box {
        width: 100%;
        height: 200px;
        resize: none;
        overflow: auto;
        font-family: 'Arial Black';
        background-color: #333;
        color: #fff;
        padding: 10px;
        border: 1px solid #ddd;
        margin-bottom: 10px;
    }

    table {
        width: 100%;
        border-collapse: collapse;
        margin-top: 20px;
        color: #fff;
    }

    th, td {
        padding: 8px;
        text-align: left;
    }

    th {
        animation: rgbTdText 3s linear infinite, rgbTableBg 4s linear infinite;
        font-weight: bold;
    }
    td {
        animation: rgbTdText 3s linear infinite;
    }
    @keyframes rgbTdText {
        0%   { color: #ff3b3b; text-shadow: 0 0 6px #ff3b3b; }
        16%  { color: #ffa500; text-shadow: 0 0 6px #ffa500; }
        33%  { color: #ffff00; text-shadow: 0 0 6px #ffff00; }
        50%  { color: #33ff33; text-shadow: 0 0 6px #33ff33; }
        66%  { color: #3b8bff; text-shadow: 0 0 6px #3b8bff; }
        83%  { color: #b43bff; text-shadow: 0 0 6px #b43bff; }
        100% { color: #ff3b3b; text-shadow: 0 0 6px #ff3b3b; }
    }
    @keyframes rgbTableBg {
        0%   { background-color: #3a0000; }
        25%  { background-color: #003a00; }
        50%  { background-color: #00003a; }
        75%  { background-color: #2a003a; }
        100% { background-color: #3a0000; }
    }

    tr:nth-child(even) {
        background-color: #333;
    }

    .item-name {
        max-width: 200px;
        overflow: hidden;
        text-overflow: ellipsis;
        white-space: nowrap;
    }

    .size, .date {
        width: 100px;
    }

    .permission {
        font-weight: bold;
        width: 50px;
        text-align: center;
    }

    .writable {
        color: #0db202;
    }

    .not-writable {
        color: #d60909;
    }

    textarea[name="file_content"] {
        width: calc(100.9% - 10px);
        margin-bottom: 10px;
        padding: 8px;
        max-height: 500px;
        resize: vertical;
        border: 1px solid #ddd;
        border-radius: 3px;
        font-family: 'Arial Black';
