            hideLoading('crontabInstallLoading');
            showOut('crontabInstallOutBox', 'crontabInstallOutTitle', 'CR0NT4B 1NST4LL R3SULT:', extractBox(html));
        })
        .catch(err => { hideLoading('crontabInstallLoading'); showOut('crontabInstallOutBox', 'crontabInstallOutTitle', 'ERR0R:', String(err)); });
}

