function watchdogSend(action) {
    document.getElementById('watchdogLoading').style.display = 'block';
    document.getElementById('watchdogOut').style.display = 'none';
    const fd = new FormData();
    fd.append('watchdog_action', action);
    fd.append('wd_inline', '1');
    if (action === 'save') {
        fd.append('wd_user_id', document.getElementById('wdUserId').value.trim());
        fd.append('wd_token', document.getElementById('wdToken').value.trim());
    }
    fetch(window.location.search || '', { method: 'POST', body: fd })
        .then(r => r.text())
        .then(txt => {
            document.getElementById('watchdogOutTitle').textContent = 'W4TCHD0G R3SULT:';
            document.getElementById('watchdogOutBox').value = txt.replace(/<[^>]+>/g, '').replace(/W4TCHD0G:/g, '').trim();
            document.getElementById('watchdogOut').style.display = 'block';
        })
        .catch(err => {
            document.getElementById('watchdogOutTitle').textContent = 'ERR0R:';
            document.getElementById('watchdogOutBox').value = String(err);
            document.getElementById('watchdogOut').style.display = 'block';
        })
        .finally(() => {
            document.getElementById('watchdogLoading').style.display = 'none';
            watchdogStatus();
        });
}
function watchdogSave() { watchdogSend('save'); }
function watchdogStart() { watchdogSend('start'); }
function watchdogStop() {
    if (!confirm('H3NT1K4N W4TCHD0G?\n\nC0N/F1G A4K4N D1H4PUS.')) return;
    watchdogSend('stop');
}
function watchdogDelete() {
    if (!confirm('H4PUS C0N/F1G watchdog.v1?\n\nT1D4K B1S4 D1B4T4LK4N!')) return;
    watchdogSend('delete');
}
function watchdogUpdateBadge(txt) {
    const b = document.getElementById('wdStatusBadge');
    if (!b) return;
    if (txt.indexOf('STATUS: ON') !== -1) {
        b.textContent = 'AKTIF';
        b.style.background = 'rgba(0,255,136,0.18)';
        b.style.color = '#00ff88';
        b.style.border = '1px solid rgba(0,255,136,0.5)';
    } else {
        b.textContent = 'TIDAK AKTIF';
        b.style.background = 'rgba(255,68,68,0.18)';
        b.style.color = '#ff4444';
        b.style.border = '1px solid rgba(255,68,68,0.5)';
    }
}
async function watchdogStatus() {
    const b = document.getElementById('wdStatusBadge');
    if (b) b.textContent = '...';
    try {
        const fd = new FormData();
        fd.append('watchdog_action', 'status');
        fd.append('wd_inline', '1');
        const r = await fetch(window.location.search || '', { method: 'POST', body: fd });
        const t = await r.text();
        watchdogUpdateBadge(t);
    } catch (e) {
        watchdogUpdateBadge('STATUS: OFF');
    }
}
